def maxWeight(n, edges, k, t):
    mask = (1 << t) - 1          # keep only sums 0 .. t-1
    dp = [1] * n                 # dp[v]: bitset of achievable sums ending at v; start: sum 0 with 0 edges
    for _ in range(k):
        new = [0] * n
        for u, v, w in edges:
            if dp[u]:
                new[v] |= (dp[u] << w) & mask
        dp = new
    best = 0
    for bits in dp:
        best |= bits
    return best.bit_length() - 1 if best else -1
